 "content": "def transform(grid):
    # Four vertically stacked 3x6 layers. The upper 5 layer is opaque;
    # beneath it, 4 overrides 8, and 8 overrides 2 where masks overlap.
    h = len(grid) // 4
    w = len(grid[0])
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                out[r][c] = 5
                continue
            for band in (2, 3, 1):  # priority: 4 > 8 > 2
                color = grid[band * h + r][c]
                if color:
                    out[r][c] = color
    return out
